        # Within the widget, find the link for 'November 2025'
        november_link = archives_widget.get_by_role("link", name="November 2025")
        if await november_link.count() > 0:
            await november_link.click()
            return
        else:
            print("Link 'November 2025' not found within the Archives widget.")
    else:
        print("Archives widget not found on the current page after comprehensive search.")

